package com.rwi.myrepublic.nisa.internal;import com.rwi.myrepublic.nisa.NisaConfig;import java.io.IOException;import java.net.CookieManager;import java.net.URI;import java.net.URLEncoder;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.nio.charset.StandardCharsets;import java.time.Duration;public class NisaFatLossClient{private final NisaConfig config;private final HttpClient httpClient;private final NisaAuthClient authClient;public
NisaFatLossClient(){this.config=NisaConfig.getInstance();this.httpClient=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectionTimeout())).followRedirects(HttpClient.Redirect.NORMAL).cookieHandler(new CookieManager()).build();this.authClient=new NisaAuthClient(config,httpClient);}public String detectFatLoss()throws IOException,InterruptedException{String token=authClient.getToken();String url=config.getApiBaseUrl()+
"/transaction/fatlossticketing/fat-loss-detection";HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization", "Bearer "+token).header("Content-Type", "application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).GET().build();HttpResponse<String>response=httpClient.send(request,HttpResponse.BodyHandlers.ofString());int statusCode=response.statusCode();String responseBody=response.body();if(statusCode!=200){throw new
IOException("NISA fat-loss-detection API returned HTTP "+statusCode+ " | Body: "+responseBody);}return responseBody;}public String getSegmentProblemDetail(String area,String hostname,String fat)throws IOException,InterruptedException{String token=authClient.getToken();String url=config.getApiBaseUrl()+ "/transaction/fatlossticketing/segment-problem-detail"+ "?area="+urlEncode(area)+ "&hostname="+urlEncode(hostname)+ "&fat="+urlEncode(fat);HttpRequest
request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization", "Bearer "+token).header("Content-Type", "application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).GET().build();HttpResponse<String>response=httpClient.send(request,HttpResponse.BodyHandlers.ofString());int statusCode=response.statusCode();String responseBody=response.body();if(statusCode!=200){throw new IOException("NISA segment-problem-detail API returned HTTP "+statusCode+
" | Body: "+responseBody);}return responseBody;}private String urlEncode(String value){return URLEncoder.encode(value==null? "":value,StandardCharsets.UTF_8);}}